import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Каркасные дома: сайт с каталогом проектов, построенными домами и заявкой на смету"}>
      <p>{"Мы строим каркасные дома под ключ в Вологде и области, восемь лет на рынке, своя бригада и небольшое производство домокомплектов. Нужен сайт из нескольких разделов. Каталог проектов: у каждого проекта страница с планировкой, площадью, числом комнат, ценой «от» и вариантами комплектации (тёплый контур, под отделку, под ключ). Раздел построенных домов с фото по этапам стройки и отзывом хозяев. Страницы про технологию, ипотеку и как мы работаем по договору, статьи о выборе участка и фундамента, контакты и как доехать до офиса. На странице проекта человек оставляет заявку на расчёт сметы: имя, телефон, район участка и выбранная комплектация. Заявки идут менеджеру на почту и в список заявок. Проекты, фото и статьи добавляет наш менеджер сам. Хотим основательный, тёплый сайт с деревом и светом, без стоковых улыбок. Для партнёров из Финляндии пишет инженер клиент, её почта клиент."}</p>
      <ul>
        <li>{"Каталог проектов"}</li>
        <li>{"Комплектации проекта"}</li>
        <li>{"Построенные дома"}</li>
        <li>{"Заявка на расчёт сметы"}</li>
      </ul>
      <p>{"Заявка приходит менеджеру на почту"}</p>
      <p>{"Менеджер сам добавляет проекты и статьи"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
